import sys
from collections import deque, Counter

def transform(grid):
    R, C = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = [[False]*C for _ in range(R)]
    for i in range(R):
        for j in range(C):
            if grid[i][j] != bg and not seen[i][j]:
                q = deque([(i,j)]); seen[i][j]=True
                comp=[]
                while q:
                    r,c=q.popleft(); comp.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<R and 0<=nc<C and not seen[nr][nc] and grid[nr][nc]!=bg:
                            seen[nr][nc]=True; q.append((nr,nc))
                rs=[r for r,_ in comp]; cs=[c for _,c in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                interior=[(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1) if grid[r][c]==bg]
                fill = 7 if len(interior)%2==1 else 2
                for r,c in interior:
                    out[r][c]=fill
    return out
